From d983c2d7889fe702377a38bb30e13ef213672999 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:26:30 +0100
Subject: [PATCH] input: update pointer focus when a window is shown or hidden

When an auto-hide panel slid in under a still pointer, the pointer focus
was not updated until the next motion event, so the panel got no hover and
no tooltips. Now input devices update their focus when hiding changes.

BUG: 518795
---
 src/input.cpp | 6 ++++++
 1 file changed, 6 insertions(+)

diff --git a/src/input.cpp b/src/input.cpp
index 327e713bc3..7b56d7f2c5 100644
--- a/src/input.cpp
+++ b/src/input.cpp
@@ -3616,6 +3616,12 @@ void InputDeviceHandler::init()
 {
     connect(workspace(), &Workspace::stackingOrderChanged, this, &InputDeviceHandler::update);
     connect(workspace(), &Workspace::windowMinimizedChanged, this, &InputDeviceHandler::update);
+    auto setupHiddenConnection = [this](Window *window) {
+        connect(window, &Window::hiddenChanged, this, &InputDeviceHandler::update);
+    };
+    const auto windows = workspace()->windows();
+    std::for_each(windows.begin(), windows.end(), setupHiddenConnection);
+    connect(workspace(), &Workspace::windowAdded, this, setupHiddenConnection);
     connect(VirtualDesktopManager::self(), &VirtualDesktopManager::currentChanged, this, &InputDeviceHandler::update);
 }

